+#define WS_MSECS_PER_SEC	(1000)
+#define WS_USECS_PER_SEC	(1000*1000)
+#define WS_NSECS_PER_SEC	(1000*1000*1000)
+
+#define WS_NSECS_PER_MSEC	(WS_NSECS_PER_SEC/WS_MSECS_PER_SEC)
